package org.mockito.internal.util;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.cglib.proxy.Callback;
import org.mockito.cglib.proxy.Factory;
import org.mockito.exceptions.misusing.NotAMockException;
import org.mockito.internal.InvocationNotifierHandler;
import org.mockito.internal.MockHandler;
import org.mockito.internal.MockHandlerInterface;
import org.mockito.internal.creation.MethodInterceptorFilter;
import org.mockito.internal.creation.MockSettingsImpl;
import org.mockito.internal.creation.jmock.ClassImposterizer;
import org.mockito.internal.util.reflection.LenientCopyTool;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MockUtil_createMock_TriageGen0Test {

    private MockUtil mockUtil;

    @Mock
    private MockCreationValidator creationValidator;

    @Mock
    private ClassImposterizer classImposterizer;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Note: Since ClassImposterizer.INSTANCE is a singleton accessed via static call, 
        // in a real environment we would use PowerMock or similar to mock it.
        // For this unit test, we assume the environment allows the execution of the logic.
        mockUtil = new MockUtil(creationValidator);
    }

    public interface ExtraInterface {}
    public interface AnotherInterface {}

    public static class TestClass implements Serializable {
        public void doSomething() {}
    }

    public static class NonSerializableClass {
        public void doSomething() {}
    }

    @Test
    public void testCreateMock_Basic() {
        MockSettingsImpl settings = new MockSettingsImpl();

        TestClass mockInstance = mockUtil.createMock(TestClass.class, settings);

        assertNotNull(mockInstance);
        verify(creationValidator).validateType(TestClass.class);
        verify(creationValidator).validateExtraInterfaces(TestClass.class, null);
        verify(creationValidator).validateMockedType(TestClass.class, null);
    }

    @Test
    public void testCreateMock_WithExtraInterfacesAndSerializable() {
        MockSettingsImpl settings = new MockSettingsImpl();
        settings.setExtraInterfaces(new Class<?>[]{ExtraInterface.class});
        settings.setSerializable(true);

        TestClass mockInstance = mockUtil.createMock(TestClass.class, settings);

        assertNotNull(mockInstance);
        verify(creationValidator).validateExtraInterfaces(TestClass.class, new Class<?>[]{ExtraInterface.class});
    }

    @Test
    public void testCreateMock_NotSerializableNoExtraInterfaces() {
        MockSettingsImpl settings = new MockSettingsImpl();
        settings.setSerializable(false);
        settings.setExtraInterfaces(null);

        NonSerializableClass mockInstance = mockUtil.createMock(NonSerializableClass.class, settings);

        assertNotNull(mockInstance);
        verify(creationValidator).validateExtraInterfaces(NonSerializableClass.class, null);
    }

    @Test
    public void testCreateMock_WithSpiedInstance() {
        MockSettingsImpl settings = new MockSettingsImpl();
        TestClass realInstance = new TestClass();
        TestClass spyInstance = spy(realInstance);
        settings.setSpiedInstance(spyInstance);

        TestClass mockInstance = mockUtil.createMock(TestClass.class, settings);

        assertNotNull(mockInstance);
        verify(creationValidator).validateMockedType(TestClass.class, spyInstance);
        // LenientCopyTool is invoked internally
    }

    @Test
    public void testCreateMock_SerializableWithOnlyExtraInterfaces() {
        MockSettingsImpl settings = new MockSettingsImpl();
        settings.setSerializable(true);
        settings.setExtraInterfaces(new Class<?>[]{AnotherInterface.class});

        TestClass mockInstance = mockUtil.createMock(TestClass.class, settings);

        assertNotNull(mockInstance);
        // Logic verifies ancillaryTypes = concat(AnotherInterface, Serializable)
    }

    @Test(expected = RuntimeException.class)
    public void testCreateMock_ValidationFails() {
        MockSettingsImpl settings = new MockSettingsImpl();
        doReturn(null).when(creationValidator).validateType(anyClass());
        // Simulate exception from validator
        doThrow(new RuntimeException("Validation failed")).when(creationValidator).validateType(TestClass.class);

        mockUtil.createMock(TestClass.class, settings);
    }

    // Helper to handle generic type in verify
    private <T> Class<T> anyClass() {
        return (Class<T>) TestClass.class;
    }
}
